size_t i = *tabind;
size_t ncells = ckh->nslots * ckh->nentries;

for (; i < ncells; i++) {
    if (ckh->tab[i].key != nullptr) {
        *key = ckh->tab[i].key;
        *data = ckh->tab[i].data;
        *tabind = i + 1;
        return false;
    }
}

*tabind = ncells;
*key = nullptr;
*data = nullptr;
return true;
